code.formula:
@Command([EditDocument]; "1");

@If(Dept= "";			@Return(@Do(@Command([EditGotoField];"Dept");			@Prompt([Ok];"Missing Value";"Please select the Department!")));"");
@If(Period= "";			@Return(@Do(@Command([EditGotoField];"Period");		@Prompt([Ok];"Missing Value";"Please select the Period!")));"");

@If(Period= "July - December (Half Yearly)" & YS1="";
								@Return(@Do(@Command([EditGotoField];"Period");		@Prompt([Ok];"Missing Value";"Please select the Year selection!")));"");
@If(Period= "July - June (Yearly)" & YS_2="";
								@Return(@Do(@Command([EditGotoField];"Period");		@Prompt([Ok];"Missing Value";"Please select the Year selection!")));"");

@If(HOD= "";			@Return(@Do(@Command([EditGotoField];"HOD");			@Prompt([Ok];"Missing Value";"Please select the HOD!")));"");
@If(PreDesg= "";		@Return(@Do(@Command([EditGotoField];"PreDesg");	@Prompt([Ok];"Missing Value";"Please state your designation!")));"");
@If(RevDesg= "";	@Return(@Do(@Command([EditGotoField];"RevDesg");	@Prompt([Ok];"Missing Value";"Please state the HOD's designation!")));"");

FIELD CA 			:= "Submitted";
FIELD PreName	:= @V3UserName;
FIELD PreDate 	:= @Today ;
FIELD RemDate	:= @Adjust(@Today;0;0;3;0;0;0);

@Command([FileSave]);
@MailSend(HOD;Defcc:CC;NULL;"Pancen Departmental KRA/KPI - Submitted for Verification - [" + Dept + "] - " + RunningNo;NULL;"Please follow this doclink  ------> ";[IncludeDoclink]);

@Command([ViewRefreshFields]);
@PostedCommand([FileSave]);
@Command([FileCloseWindow])

@Command([EditDocument]; "1");

FIELD CA 			:= "Reviewed";
FIELD RevName	:= @V3UserName;
FIELD RevDate 	:= @Today ;

@MailSend(DocAuthor;Defcc:CC;NULL;"Pancen Departmental KRA/KPI - REVIEWED - [" + Dept + "] - " + RunningNo;NULL;"Please follow this doclink  ------> ";[IncludeDoclink]);

@Command([ViewRefreshFields]);
@PostedCommand([FileSave]);
@Command([FileCloseWindow])

@Command([EditDocument]; "1");

FIELD CA 			:= "Rejected";
FIELD RevName	:= @V3UserName;
FIELD RevDate 	:= @Today ;
FIELD RejCom := @Prompt([OkCancelEdit]; "Enter Your Comment"; "Please state the reason for rejection.";"");

@MailSend(DocAuthor;Defcc:CC;NULL;"Pancen Departmental KRA/KPI - REJECTED - [" + Dept + "] - " + RunningNo;NULL;"Comment : "+ RejCom +  @NewLine+ @NewLine  +"Please follow this doclink  ------> ";[IncludeDoclink]);

@Command([ViewRefreshFields]);
@PostedCommand([FileSave]);
@Command([FileCloseWindow])

@Command([EditDocument]; "1");

@If(Dept= "";			@Return(@Do(@Command([EditGotoField];"Dept");			@Prompt([Ok];"Missing Value";"Please select the Department!")));"");

