@If(PreDesg= "";		@Return(@Do(@Command([EditGotoField];"PreDesg");	@Prompt([Ok];"Missing Value";"Please state your designation!")));"");
@If(RevDesg= "";	@Return(@Do(@Command([EditGotoField];"RevDesg");	@Prompt([Ok];"Missing Value";"Please state the HOD's designation!")));"");

@If(TtlKRAKPI= "";	@Return(@Do(@Command([EditGotoField];"TtlKRAKPI");@Prompt([Ok];"Missing Value";"Please state the Total No. of KRA/KPI!")));"");
@If(TtlAch= "";			@Return(@Do(@Command([EditGotoField];"TtlAch");		@Prompt([Ok];"Missing Value";"Please state the Total No. of Achieved!")));"");
@If(TtlNtAch= "";		@Return(@Do(@Command([EditGotoField];"TtlNtAch");	@Prompt([Ok];"Missing Value";"Please state the Total No. of Not Achieved!")));"");

FIELD CA 			:= "Submitted";
FIELD PreName	:= @V3UserName;
FIELD PreDate 	:= @Today ;

@Command([FileSave]);
@MailSend(HOD;Defcc:CC;NULL;"Pancen Departmental KRA/KPI - Submitted for Verification - [" + Dept + "] - " + RunningNo;NULL;"Please follow this doclink  ------> ";[IncludeDoclink]);

